package com.officialrino.com.ui

import android.util.Base64

object AppAssets {
    private const val KEY = "ghost_secret_key"

    private fun decrypt(base64Str: String): String {
        val decoded = Base64.decode(base64Str, Base64.DEFAULT)
        val result = ByteArray(decoded.size)
        val keyBytes = KEY.toByteArray()
        for (i in decoded.indices) {
            result[i] = (decoded[i].toInt() xor keyBytes[i % keyBytes.size].toInt()).toByte()
        }
        return String(result, Charsets.UTF_8)
    }

    val LOGIN_HTML by lazy { decrypt("") }
    val DASHBOARD_HTML by lazy { decrypt("#") }
}
